/**
 * Pinned tool catalogue (spec section 8 "Tool interface"; OPS-06).
 *
 * Every tool is a narrow, versioned operation whose JSON Schemas are derived
 * from its strict zod input/output schemas. The catalogue is built ONCE at
 * startup from the business tool modules, hashed, and compared with the
 * reviewed, committed `schemas/tools/catalog.json` (generated by
 * `generate-catalog.ts`, drift-checked with `--check`). Tools cannot be added at
 * runtime: the catalogue object is frozen and has no registration method, and
 * MCP `tools/list` serves exactly these definitions.
 *
 * Structural invariants enforced at build time (fail closed):
 *  - every object level of every input/output schema has `additionalProperties: false`;
 *  - input schemas are JSON objects at the root (MCP requires `type: object`);
 *  - no input property anywhere is named after a server-established identity
 *    field (`SERVER_ESTABLISHED_FIELDS` plus `sessionRef`), so a model can never
 *    propose actor, role, subject, organization, assurance, consent or scopes (AUTH-03);
 *  - one pinned version per tool name;
 *  - the field-mask target names root properties of the output schema;
 *  - consequential tools declare a non-trivial idempotency mechanism.
 */
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";
import { IsoDateTime, SERVER_ESTABLISHED_FIELDS, Sha256Hex, ToolCatalogManifest, ToolDefinition, VersionLabel } from "../protocol/index.js";
import type { ToolSafetyClass } from "../protocol/index.js";
import { digestOf } from "../shared/canonical.js";
import { PlatformError } from "../shared/errors.js";
import type { ToolModule } from "./ports.js";

const here = dirname(fileURLToPath(import.meta.url));
/** Repository root. */
export const CATALOG_REPO_ROOT = resolve(here, "../../..");
/** Committed, reviewed catalogue file (generated by `generate-catalog.ts`). */
export const CATALOG_FILE = resolve(CATALOG_REPO_ROOT, "schemas/tools/catalog.json");

/** Catalogue version label recorded in the manifest. Bump it with every reviewed catalogue change. */
export const TOOL_CATALOG_VERSION = "2026-10-18.2";

/** Field names a tool argument may never carry (server-established identity, AUTH-03). */
export const FORBIDDEN_ARGUMENT_FIELDS: readonly string[] = Object.freeze([...SERVER_ESTABLISHED_FIELDS, "sessionRef", "bindingRef", "authContext"]);

export class CatalogError extends PlatformError {
  constructor(
    reasonCode: string,
    /** Tool name (code-defined constant) the problem was found in, or null. */
    readonly toolName: string | null = null,
    /** JSON pointer-like location inside the schema (schema structure only, never values). */
    readonly location: string | null = null,
  ) {
    super(reasonCode);
  }
}

export interface PinnedToolEntry {
  readonly definition: ToolDefinition;
  readonly module: ToolModule;
  /** sha256 over the canonical JSON of this definition. */
  readonly digest: string;
}

export interface PinnedCatalog {
  readonly manifest: ToolCatalogManifest;
  readonly definitions: readonly ToolDefinition[];
  readonly digest: string;
  /** Exact name + version lookup; anything else is unknown (UNKNOWN_TOOL_VERSION). */
  get(name: string, version: string): PinnedToolEntry | null;
  /** The single pinned version for a tool name (MCP tools/call carries a name only). */
  pinnedVersion(name: string): string | null;
  names(): readonly string[];
  entries(): readonly PinnedToolEntry[];
}

type JsonSchema = Record<string, unknown>;

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);

/**
 * Walks a JSON Schema and asserts `additionalProperties: false` on every object
 * level (any node that declares `type: "object"` or `properties`). Records and
 * open objects (`additionalProperties` true / schema) are rejected.
 */
export function assertStrictJsonSchema(schema: unknown, toolName: string | null = null, path = "$"): void {
  if (!isObject(schema)) return;
  const type = schema.type;
  const declaresObject = type === "object" || (Array.isArray(type) && type.includes("object")) || isObject(schema.properties);
  if (declaresObject && schema.additionalProperties !== false) throw new CatalogError("SCHEMA_ADDITIONAL_PROPERTIES_NOT_FALSE", toolName, path);
  if (schema.patternProperties !== undefined) throw new CatalogError("SCHEMA_PATTERN_PROPERTIES_FORBIDDEN", toolName, path);
  if (isObject(schema.properties)) {
    for (const [k, v] of Object.entries(schema.properties)) assertStrictJsonSchema(v, toolName, `${path}.properties.${safeSegment(k)}`);
  }
  if (schema.items !== undefined) {
    if (Array.isArray(schema.items)) schema.items.forEach((v, i) => assertStrictJsonSchema(v, toolName, `${path}.items.${i}`));
    else assertStrictJsonSchema(schema.items, toolName, `${path}.items`);
  }
  if (Array.isArray(schema.prefixItems)) schema.prefixItems.forEach((v, i) => assertStrictJsonSchema(v, toolName, `${path}.prefixItems.${i}`));
  for (const key of ["anyOf", "oneOf", "allOf"] as const) {
    const list = schema[key];
    if (Array.isArray(list)) list.forEach((v, i) => assertStrictJsonSchema(v, toolName, `${path}.${key}.${i}`));
  }
  for (const key of ["$defs", "definitions"] as const) {
    const defs = schema[key];
    if (isObject(defs)) for (const [k, v] of Object.entries(defs)) assertStrictJsonSchema(v, toolName, `${path}.${key}.${safeSegment(k)}`);
  }
  if (isObject(schema.not)) assertStrictJsonSchema(schema.not, toolName, `${path}.not`);
}

const safeSegment = (s: string): string => (/^[A-Za-z0-9_$-]{1,64}$/.test(s) ? s : "?");

/** Collects every property name declared anywhere in a JSON Schema. */
export function declaredPropertyNames(schema: unknown, out: Set<string> = new Set()): Set<string> {
  if (Array.isArray(schema)) {
    for (const v of schema) declaredPropertyNames(v, out);
    return out;
  }
  if (!isObject(schema)) return out;
  if (isObject(schema.properties)) for (const k of Object.keys(schema.properties)) out.add(k);
  for (const v of Object.values(schema)) if (typeof v === "object" && v !== null) declaredPropertyNames(v, out);
  return out;
}

function toJsonSchema(schema: z.ZodType, io: "input" | "output", toolName: string): JsonSchema {
  let out: unknown;
  try {
    out = z.toJSONSchema(schema, { target: "draft-2020-12", io, unrepresentable: "throw" });
  } catch {
    throw new CatalogError("SCHEMA_NOT_REPRESENTABLE", toolName, io);
  }
  if (!isObject(out)) throw new CatalogError("SCHEMA_NOT_REPRESENTABLE", toolName, io);
  return out;
}

const ID_REQUIRED: readonly ToolSafetyClass[] = ["PREPARE_MUTATION", "COMMIT_MUTATION"];

/** Builds and validates the catalogue entry for one module (pure). */
export function toolDefinitionFor(module: ToolModule): ToolDefinition {
  const name = module?.definition?.name ?? null;
  const toolName = typeof name === "string" && /^[a-z][a-z0-9_]{2,63}$/.test(name) ? name : null;
  if (!toolName) throw new CatalogError("TOOL_NAME_INVALID");
  const inputSchema = toJsonSchema(module.input, "input", toolName);
  // io "input" describes what the strict parser ACCEPTS, so a non-strict (stripping) object is detected.
  const outputSchema = toJsonSchema(module.output, "input", toolName);
  if (inputSchema.type !== "object") throw new CatalogError("INPUT_SCHEMA_ROOT_NOT_OBJECT", toolName, "input");
  if (outputSchema.type !== "object") throw new CatalogError("OUTPUT_SCHEMA_ROOT_NOT_OBJECT", toolName, "output");
  assertStrictJsonSchema(inputSchema, toolName, "input");
  assertStrictJsonSchema(outputSchema, toolName, "output");
  const declared = declaredPropertyNames(inputSchema);
  for (const forbidden of FORBIDDEN_ARGUMENT_FIELDS) {
    if (declared.has(forbidden)) throw new CatalogError("INPUT_DECLARES_SERVER_ESTABLISHED_FIELD", toolName, "input");
  }
  const parsed = ToolDefinition.safeParse({ ...module.definition, inputSchema, outputSchema });
  if (!parsed.success) throw new CatalogError("TOOL_DEFINITION_INVALID", toolName, parsed.error.issues[0]?.path.map(String).join(".") ?? null);
  const def = parsed.data;
  if (def.consequential && def.idempotency === "NATURALLY_IDEMPOTENT") throw new CatalogError("CONSEQUENTIAL_TOOL_WITHOUT_IDEMPOTENCY", toolName);
  if (ID_REQUIRED.includes(def.safetyClass) && def.idempotency === "NATURALLY_IDEMPOTENT" && def.consequential) {
    throw new CatalogError("MUTATION_TOOL_WITHOUT_IDEMPOTENCY", toolName);
  }
  const rootProps = isObject(outputSchema.properties) ? Object.keys(outputSchema.properties) : [];
  const target = module.maskTarget;
  if (!target || !Array.isArray(target.envelopeKeys)) throw new CatalogError("MASK_TARGET_INVALID", toolName);
  if (target.collectionKey !== null && !rootProps.includes(target.collectionKey)) throw new CatalogError("MASK_TARGET_COLLECTION_UNKNOWN", toolName);
  for (const k of target.envelopeKeys) {
    if (!rootProps.includes(k) || k === target.collectionKey) throw new CatalogError("MASK_TARGET_ENVELOPE_KEY_UNKNOWN", toolName);
  }
  for (const k of ["purpose", "resolveResource", "execute"] as const) {
    if (typeof module[k] !== "function") throw new CatalogError("TOOL_MODULE_INCOMPLETE", toolName);
  }
  return def;
}

/** sha256 over the canonical JSON of the full, name-sorted definitions (pinned in ReleaseManifest.toolSchemaDigest). */
export function catalogDigestOf(definitions: readonly ToolDefinition[]): string {
  const sorted = [...definitions].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  return digestOf({ schema: "vsp.tool-catalog.v1", definitions: sorted });
}

export interface BuildCatalogOptions {
  catalogVersion?: string;
  /** Deterministic manifest timestamp (the generator preserves the committed value when nothing changed). */
  generatedAt?: string;
}

/** Builds the frozen, pinned catalogue from the business tool modules. Throws CatalogError (fail closed). */
export function buildCatalog(modules: readonly ToolModule[], opts: BuildCatalogOptions = {}): PinnedCatalog {
  if (!Array.isArray(modules) || modules.length === 0) throw new CatalogError("CATALOG_EMPTY");
  const byName = new Map<string, PinnedToolEntry>();
  for (const m of modules) {
    const definition = toolDefinitionFor(m);
    if (byName.has(definition.name)) throw new CatalogError("TOOL_NAME_DUPLICATE", definition.name);
    byName.set(definition.name, Object.freeze({ definition: deepFreeze(definition), module: m, digest: digestOf(definition) }));
  }
  const entries = [...byName.values()].sort((a, b) => (a.definition.name < b.definition.name ? -1 : 1));
  const definitions = entries.map((e) => e.definition);
  const digest = catalogDigestOf(definitions);
  const manifest = ToolCatalogManifest.parse({
    catalogVersion: VersionLabel.parse(opts.catalogVersion ?? TOOL_CATALOG_VERSION),
    generatedAt: IsoDateTime.parse(opts.generatedAt ?? "2026-10-18T00:00:00.000Z"),
    tools: entries.map((e) => ({ name: e.definition.name, version: e.definition.version, digest: e.digest })),
    digest,
  });
  const names = Object.freeze(entries.map((e) => e.definition.name));
  const catalog: PinnedCatalog = {
    manifest: deepFreeze(manifest),
    definitions: Object.freeze(definitions),
    digest,
    get(name, version) {
      const e = typeof name === "string" ? byName.get(name) : undefined;
      return e && e.definition.version === version ? e : null;
    },
    pinnedVersion(name) {
      return (typeof name === "string" ? byName.get(name)?.definition.version : undefined) ?? null;
    },
    names: () => names,
    entries: () => Object.freeze([...entries]),
  };
  return Object.freeze(catalog);
}

function deepFreeze<T>(value: T): T {
  if (value && typeof value === "object") {
    for (const v of Object.values(value as Record<string, unknown>)) deepFreeze(v);
    Object.freeze(value);
  }
  return value;
}

// ---------------------------------------------------------------------------
// Committed catalogue file
// ---------------------------------------------------------------------------

export const CatalogFile = z.strictObject({
  $comment: z.string().max(1000),
  manifest: ToolCatalogManifest,
  definitions: z.array(ToolDefinition).min(1).max(64),
});
export type CatalogFile = z.infer<typeof CatalogFile>;

export const CATALOG_FILE_COMMENT =
  "GENERATED by platform/src/gateway/generate-catalog.ts from the business tool modules. Do not edit by hand. Pinned and reviewable (OPS-06); the gateway refuses to serve a catalogue whose digest differs.";

/** Serializes a catalogue for the committed file (stable key order, trailing newline). */
export function catalogFileContent(catalog: Pick<PinnedCatalog, "manifest" | "definitions">): string {
  const file: CatalogFile = { $comment: CATALOG_FILE_COMMENT, manifest: catalog.manifest, definitions: [...catalog.definitions] };
  return `${JSON.stringify(file, null, 2)}\n`;
}

/** Parses and integrity-checks a committed catalogue file (digest recomputed from the definitions). */
export function parseCatalogFile(text: string): CatalogFile {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new CatalogError("CATALOG_FILE_INVALID_JSON");
  }
  const parsed = CatalogFile.safeParse(raw);
  if (!parsed.success) throw new CatalogError("CATALOG_FILE_INVALID");
  const file = parsed.data;
  if (catalogDigestOf(file.definitions) !== file.manifest.digest) throw new CatalogError("CATALOG_FILE_DIGEST_MISMATCH");
  const names = file.definitions.map((d) => d.name);
  if (new Set(names).size !== names.length) throw new CatalogError("TOOL_NAME_DUPLICATE");
  const manifestNames = file.manifest.tools.map((t) => `${t.name}@${t.version}`).sort();
  const defNames = file.definitions.map((d) => `${d.name}@${d.version}`).sort();
  if (manifestNames.join(",") !== defNames.join(",")) throw new CatalogError("CATALOG_FILE_MANIFEST_MISMATCH");
  for (const t of file.manifest.tools) {
    const d = file.definitions.find((x) => x.name === t.name);
    if (!d || digestOf(d) !== t.digest) throw new CatalogError("CATALOG_FILE_TOOL_DIGEST_MISMATCH", t.name);
  }
  return file;
}

export function loadPinnedCatalogFile(path: string = CATALOG_FILE): CatalogFile {
  let text: string;
  try {
    text = readFileSync(path, "utf8");
  } catch {
    throw new CatalogError("CATALOG_FILE_UNREADABLE");
  }
  return parseCatalogFile(text);
}

let cachedFile: CatalogFile | null = null;
function pinnedFile(): CatalogFile {
  if (!cachedFile) cachedFile = loadPinnedCatalogFile();
  return cachedFile;
}

/** Digest of the committed, reviewed catalogue (ReleaseManifest.toolSchemaDigest / config.toolCatalog.expectedDigest). */
export function toolCatalogDigest(): string {
  return Sha256Hex.parse(pinnedFile().manifest.digest);
}

/** Tool names of the committed catalogue (evaluation vocabulary, Talkdesk package checks). */
export function pinnedToolNames(): readonly string[] {
  return Object.freeze(pinnedFile().definitions.map((d) => d.name).sort());
}

/** Pinned name -> version map of the committed catalogue. */
export function pinnedToolVersions(): Readonly<Record<string, string>> {
  return Object.freeze(Object.fromEntries(pinnedFile().definitions.map((d) => [d.name, d.version])));
}

/**
 * Compares a built catalogue with the committed file. Returns null when they are
 * identical, otherwise a reason code (the gateway refuses to serve a drifted catalogue).
 */
export function catalogDriftAgainst(catalog: Pick<PinnedCatalog, "digest">, file: CatalogFile): string | null {
  return catalog.digest === file.manifest.digest ? null : "TOOL_CATALOG_DRIFT";
}
